-- Transactional policy/guard fixtures only. Real byte operations are covered by E2E.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select no_plan();
select is((select public from storage.buckets where id='story-assets'),false,'Story bucket is private');
select is((select file_size_limit from storage.buckets where id='story-assets'),2097152::bigint,'Bucket limits bytes');
select is((select allowed_mime_types from storage.buckets where id='story-assets'),array['image/png','image/jpeg','image/webp'],'Bucket permits only raster MIME types');
select ok(not has_column_privilege('authenticated','public.assets','id','INSERT'),'Cannot supply asset identity');
select ok(not has_column_privilege('authenticated','public.assets','created_at','INSERT'),'Cannot supply asset timestamp');
select ok(not has_table_privilege('authenticated','public.assets','UPDATE'),'Metadata cannot be changed or reparented');
select ok(not has_function_privilege('authenticated','private.guard_asset_object_delete()','EXECUTE'),'Cannot call delete guard directly');
select ok(not has_function_privilege('anon','private.guard_asset_object_delete()','EXECUTE'),'Anonymous cannot call delete guard');
select is((select proconfig[1] from pg_proc where oid='private.guard_asset_object_delete()'::regprocedure),'search_path=""','Definer guard pins search path');
select ok((select prosecdef from pg_proc where oid='private.guard_asset_object_delete()'::regprocedure),'Guard can inspect Storage during a parent cascade');
select is((select count(*) from pg_policies where schemaname='storage' and policyname like 'story_assets_%'),3::bigint,'Only select, insert and delete Storage policies');
select set_config('request.jwt.claims','{"role":"authenticated","sub":"11111111-1111-4111-8111-111111111111"}',true);
set local role authenticated;
select lives_ok($$insert into public.assets(story_id,kind,storage_path,mime_type) values ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','hero','11111111-1111-4111-8111-111111111111/aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1/ffffffff-ffff-4fff-8fff-ffffffffffff.webp','image/webp')$$,'Owner reserves hero metadata');
select throws_ok($$insert into public.assets(story_id,kind,storage_path,mime_type) values ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2','hero','22222222-2222-4222-8222-222222222222/aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2/ffffffff-ffff-4fff-8fff-ffffffffffff.webp','image/webp')$$,'42501',null,'Cannot forge owner namespace');
select throws_ok($$insert into public.assets(story_id,kind,storage_path,mime_type) values ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2','generated','11111111-1111-4111-8111-111111111111/aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2/ffffffff-ffff-4fff-8fff-ffffffffffff.webp','image/webp')$$,'42501',null,'Cannot forge generated output');
select throws_ok($$insert into storage.objects(bucket_id,name) values ('story-assets','11111111-1111-4111-8111-111111111111/aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2/ffffffff-ffff-4fff-8fff-ffffffffffff.webp')$$,'42501',null,'Object needs matching reserved metadata');
select throws_ok($$insert into storage.objects(bucket_id,name) values ('story-assets','11111111-1111-4111-8111-111111111111/../escape.webp')$$,'42501',null,'Traversal path is unauthorized');
select lives_ok($$insert into storage.objects(bucket_id,name) select 'story-assets',storage_path from public.assets$$,'Owner may upload at reserved path');
select is((select count(*) from storage.objects where bucket_id='story-assets'),1::bigint,'Owner can read own object');
select is_empty($$update storage.objects set name=name where bucket_id='story-assets' returning id$$,'Objects cannot be overwritten or moved');
select throws_ok($$delete from public.assets$$,'23503',null,'Metadata deletion blocked while stored object exists');
select throws_ok($$delete from public.stories where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1'$$,'23503',null,'Cascaded metadata deletion also blocked');
reset role;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"22222222-2222-4222-8222-222222222222"}',true);
set local role authenticated;
select is_empty($$select * from storage.objects where bucket_id='story-assets'$$,'Bob cannot list Alice objects');
select is_empty($$delete from public.assets returning id$$,'Bob cannot delete Alice metadata');
select throws_ok($$insert into storage.objects(bucket_id,name) values ('story-assets','11111111-1111-4111-8111-111111111111/aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1/ffffffff-ffff-4fff-8fff-ffffffffffff.webp')$$,'42501',null,'Bob cannot upload into Alice namespace');
select throws_ok($$insert into public.assets(story_id,kind,storage_path,mime_type) values ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2','hero','22222222-2222-4222-8222-222222222222/aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2/ffffffff-ffff-4fff-8fff-ffffffffffff.webp','image/webp')$$,'42501',null,'Bob cannot reserve another story even in own namespace');
reset role;
select set_config('request.jwt.claims','{"role":"anon"}',true);
set local role anon;
select is_empty($$select * from storage.objects where bucket_id='story-assets'$$,'Anonymous cannot list private objects');
select throws_ok($$insert into storage.objects(bucket_id,name) values ('story-assets','11111111-1111-4111-8111-111111111111/aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1/ffffffff-ffff-4fff-8fff-ffffffffffff.webp')$$,'42501',null,'Anonymous cannot upload');
reset role;
select set_config('request.jwt.claims','{"role":"authenticated"}',true);
set local role authenticated;
select is_empty($$select * from storage.objects where bucket_id='story-assets'$$,'Missing uid cannot read objects');
reset role;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"11111111-1111-4111-8111-111111111111"}',true);
set local role authenticated;
-- Keep managed-table deletion protection enabled. The browser suite exercises
-- actual byte deletion and cross-owner DELETE denial through the Storage API.
select lives_ok($$insert into public.assets(story_id,kind,storage_path,mime_type) values ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2','hero','11111111-1111-4111-8111-111111111111/aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2/ffffffff-ffff-4fff-8fff-ffffffffffff.webp','image/webp')$$,'Owner can reserve a second story image');
select lives_ok($$delete from public.assets where story_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2'$$,'Owner can remove a reservation with no object');
select is_empty($$select id from public.assets where story_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2'$$,'Empty reservation removed');
select lives_ok($$delete from public.stories where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2'$$,'Story deletion succeeds without stored objects');
reset role;
select * from finish();
rollback;
